import { MeshPhysicalNodeMaterial, MeshBasicNodeMaterial } from 'three/webgpu';
import { uv, vec3, mix, step, sub, add, mul, float, smoothstep } from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const THREE = ctx.THREE;
  const { Group, Mesh, PlaneGeometry, BoxGeometry, DirectionalLight, AmbientLight } = THREE;

  const root = new Group();
  root.name = 'bento-metrics-grid';

  const vs = config.intent?.visualSpec ?? {};
  const colors = vs.colors ?? {};
  const accentHex = colors.accent || '#ff2a38';
  const paperHex = colors.paper || '#e8ecf2';
  const surfaceHex = colors.surface || '#14141a';
  const stops = colors.gradientStops ?? [{ at: 0, hex: '#101017' }, { at: 1, hex: '#1a1a22' }];
  const c0 = stops[0].hex;
  const c1 = stops[stops.length - 1].hex;

  // ---------- Backdrop: layered gradient + vignette, never flat void ----------
  const bgMat = new MeshBasicNodeMaterial();
  const bgUV = uv();
  const bgGrad = mix(vec3('#07070b'), vec3('#171720'), bgUV.y);
  const du = sub(bgUV.x, float(0.5));
  const dv = sub(bgUV.y, float(0.5));
  const r2 = add(mul(du, du), mul(dv, dv));
  const vignette = sub(float(1.0), mul(r2, float(0.45)));
  bgMat.colorNode = mul(bgGrad, vignette);
  const backdrop = new Mesh(new PlaneGeometry(8, 6.5), bgMat);
  backdrop.position.set(0, 0, -2.5);
  root.add(backdrop);

  // Subtle accent-tinted glow behind dominant cell (fills lower-left)
  const glowMat = new MeshBasicNodeMaterial();
  glowMat.transparent = true;
  glowMat.opacity = 0.15;
  glowMat.colorNode = vec3('#2a0e12');
  const glow = new Mesh(new PlaneGeometry(5, 4.5), glowMat);
  glow.position.set(-1.1, -0.2, -2.3);
  root.add(glow);

  // ---------- Lights (product-shot grade) ----------
  root.add(new AmbientLight(0xffffff, 0.45));
  const key = new DirectionalLight(0xffffff, 1.15);
  key.position.set(3, 4, 5);
  root.add(key);
  const rim = new DirectionalLight(0xff2a38, 0.55);
  rim.position.set(-4, 1.5, -2);
  root.add(rim);
  const fill = new DirectionalLight(0xa0a8b8, 0.35);
  fill.position.set(-3, -2, 4);
  root.add(fill);
  const topLight = new DirectionalLight(0xe8ecf2, 0.7);
  topLight.position.set(0, 5, 3);
  root.add(topLight);

  // ---------- Cell face material: engineered diagonal gradient + sheen band ----------
  function makeCellFaceMaterial() {
    const mat = new MeshPhysicalNodeMaterial();
    mat.metalness = 0.45;
    mat.roughness = 0.5;
    mat.clearcoat = 0.2;
    mat.clearcoatRoughness = 0.4;

    const cuv = uv();
    const diag = mul(add(cuv.x, cuv.y), float(0.5));
    const grad = mix(vec3(c0), vec3(c1), diag);

    // Hard-stop machined sheen band at 0.40 diagonal, 0.15 wide
    const inBand = step(float(0.325), diag).mul(sub(float(1.0), step(float(0.475), diag)));
    const sheen = inBand.mul(float(0.09));
    mat.colorNode = add(grad, vec3(sheen, sheen, sheen));
    return mat;
  }

  // ---------- Chamfer edge material: brushed metal that catches key light ----------
  function makeEdgeMaterial() {
    const mat = new MeshPhysicalNodeMaterial();
    mat.metalness = 0.9;
    mat.roughness = 0.3;
    mat.clearcoat = 0.2;
    mat.clearcoatRoughness = 0.3;
    mat.colorNode = vec3('#42424e');
    return mat;
  }

  // ---------- Accent tick material: emissive signal red ----------
  const tickGeo = new PlaneGeometry(0.4, 0.05);
  const tickMat = new MeshBasicNodeMaterial();
  tickMat.colorNode = vec3(accentHex).mul(float(1.6));

  // Thin accent edge material
  const accentEdgeMat = new MeshBasicNodeMaterial();
  accentEdgeMat.colorNode = vec3(accentHex).mul(float(1.2));

  // ---------- Cell builder: extruded slab + chamfer frame + accent ----------
  const cellDepth = 0.06;
  const chamfer = 0.04;

  function makeCell(w, h) {
    const group = new Group();

    // Main slab body
    const slab = new Mesh(new BoxGeometry(w, h, cellDepth), makeCellFaceMaterial());
    group.add(slab);

    // Chamfer edges — bright brushed metal strips around front perimeter
    const edgeMat = makeEdgeMaterial();

    const topEdge = new Mesh(new BoxGeometry(w, chamfer * 0.5, chamfer), edgeMat);
    topEdge.position.set(0, h / 2 - chamfer * 0.25, cellDepth / 2 + chamfer * 0.5);
    group.add(topEdge);

    const botEdge = new Mesh(new BoxGeometry(w, chamfer * 0.5, chamfer), edgeMat);
    botEdge.position.set(0, -h / 2 + chamfer * 0.25, cellDepth / 2 + chamfer * 0.5);
    group.add(botEdge);

    const leftEdge = new Mesh(new BoxGeometry(chamfer * 0.5, h, chamfer), edgeMat);
    leftEdge.position.set(-w / 2 + chamfer * 0.25, 0, cellDepth / 2 + chamfer * 0.5);
    group.add(leftEdge);

    const rightEdge = new Mesh(new BoxGeometry(chamfer * 0.5, h, chamfer), edgeMat);
    rightEdge.position.set(w / 2 - chamfer * 0.25, 0, cellDepth / 2 + chamfer * 0.5);
    group.add(rightEdge);

    // Accent tick bar — top-left inside padding
    const tick = new Mesh(tickGeo, tickMat);
    tick.position.set(-w / 2 + 0.5 + 0.2, h / 2 - 0.5, cellDepth / 2 + 0.005);
    group.add(tick);

    return group;
  }

  // ---------- Layout ----------
  const dom = makeCell(3.25, 3.5);
  dom.position.set(-1.125, 0, 0);
  root.add(dom);

  const tr = makeCell(2.0, 1.625);
  tr.position.set(1.75, 0.9375, 0);
  root.add(tr);

  const br = makeCell(2.0, 1.625);
  br.position.set(1.75, -0.9375, 0);
  root.add(br);

  // ---------- Text content ----------
  const items = config.textContent ?? config.intent?.visualSpec?.textContent ?? [];
  const T = items.length ? items : [
    { text: 'ATELIER METRICS / Q2 2026', role: 'caption' },
    { text: '0.002 mm', role: 'valueLarge' },
    { text: 'Case tolerance, CNC pass', role: 'label' },
    { text: '38 h', role: 'value' },
    { text: 'Power reserve, NA-01', role: 'label' },
    { text: '214', role: 'value' },
    { text: 'Components per calibre', role: 'label' },
  ];

  const labelColor = '#9499a6';
  const zFront = cellDepth / 2 + chamfer + 0.01;

  // Header caption — 0.5 units above grid, left-aligned to grid edge
  const header = ctx.fontAtlas.createText(T[0].text, {
    fontSize: 0.14, color: paperHex, align: 'left', letterSpacingPx: 0.012
  });
  header.position.set(-2.75, 2.25, 0.1);
  root.add(header);

  // Dominant cell text — value at 0.62 em, label at 0.5 offset below
  const domValue = ctx.fontAtlas.createText(T[1].text, {
    fontSize: 0.62, color: paperHex, align: 'left'
  });
  domValue.position.set(-2.75 + 0.5, -0.2, zFront);
  dom.add(domValue);

  const domLabel = ctx.fontAtlas.createText(T[2].text, {
    fontSize: 0.14, color: labelColor, align: 'left', letterSpacingPx: 0.008, maxWidthPx: 2.5
  });
  domLabel.position.set(-2.75 + 0.5, -0.85, zFront);
  dom.add(domLabel);

  // Top-right secondary cell text
  const trValue = ctx.fontAtlas.createText(T[3].text, {
    fontSize: 0.34, color: paperHex, align: 'left'
  });
  trValue.position.set(-1.0 + 0.5, -0.05, zFront);
  tr.add(trValue);

  const trLabel = ctx.fontAtlas.createText(T[4].text, {
    fontSize: 0.13, color: labelColor, align: 'left', letterSpacingPx: 0.008, maxWidthPx: 1.8
  });
  trLabel.position.set(-1.0 + 0.5, -0.42, zFront);
  tr.add(trLabel);

  // Bottom-right secondary cell text
  const brValue = ctx.fontAtlas.createText(T[5].text, {
    fontSize: 0.34, color: paperHex, align: 'left'
  });
  brValue.position.set(-1.0 + 0.5, -0.05, zFront);
  br.add(brValue);

  const brLabel = ctx.fontAtlas.createText(T[6].text, {
    fontSize: 0.13, color: labelColor, align: 'left', letterSpacingPx: 0.008, maxWidthPx: 1.8
  });
  brLabel.position.set(-1.0 + 0.5, -0.42, zFront);
  br.add(brLabel);

  // ---------- Entrance: stagger-cards, fade-up, dominant first ----------
  const timelines = [];
  const cells = [
    { mesh: dom, baseY: 0 },
    { mesh: tr, baseY: 0.9375 },
    { mesh: br, baseY: -0.9375 },
  ];

  cells.forEach((c, i) => {
    c.mesh.position.y = c.baseY + 0.2;
    const cellMats = [];
    c.mesh.traverse(o => {
      if (o.material && !cellMats.includes(o.material)) {
        cellMats.push(o.material);
        o.material.transparent = true;
        o.material.opacity = 0;
      }
      if (o !== c.mesh) o.visible = false;
    });

    const tl = gsap.timeline({ delay: i * 0.08 });
    tl.to(c.mesh.position, { y: c.baseY, duration: 0.5, ease: 'power2.out' }, 0);
    cellMats.forEach(m => {
      tl.to(m, { opacity: 1, duration: 0.5, ease: 'power2.out' }, 0);
    });
    tl.add(() => {
      c.mesh.traverse(o => { if (o !== c.mesh) o.visible = true; });
    }, 0.15);
    timelines.push(tl);
  });

  // Header fade-up
  const headerMats = [];
  header.traverse(o => {
    if (o.material && !headerMats.includes(o.material)) {
      headerMats.push(o.material);
      o.material.transparent = true;
      o.material.opacity = 0;
    }
  });
  header.position.y = 2.45;
  const htl = gsap.timeline({ delay: 0.32 });
  headerMats.forEach(m => {
    htl.to(m, { opacity: 1, duration: 0.5, ease: 'power2.out' }, 0);
  });
  htl.to(header.position, { y: 2.25, duration: 0.5, ease: 'power2.out' }, 0);
  timelines.push(htl);

  // ---------- Hover: press-down + weighted-settle ----------
  function attachHover(target) {
    target.userData.handlers = {
      pointerenter: () => {
        gsap.killTweensOf(target.scale);
        gsap.to(target.scale, { x: 0.97, y: 0.97, z: 0.97, duration: 0.12, ease: 'back.in(2)' });
      },
      pointerleave: () => {
        gsap.killTweensOf(target.scale);
        gsap.to(target.scale, {
          x: 1.04, y: 1.04, z: 1.04, duration: 0.45, ease: 'power4.out',
          onComplete: () => {
            gsap.to(target.scale, { x: 1, y: 1, z: 1, duration: 0.45, ease: 'power4.out' });
          }
        });
      }
    };
  }
  attachHover(dom);
  attachHover(tr);
  attachHover(br);
  root.userData.handlers = {};

  // ---------- Cleanup ----------
  const allText = [header, domValue, domLabel, trValue, trLabel, brValue, brLabel];
  const allMaterials = [bgMat, glowMat, tickMat, accentEdgeMat];
  const allGeometries = [backdrop.geometry, glow.geometry, tickGeo];

  [dom, tr, br].forEach(cell => {
    cell.traverse(o => {
      if (o.material && !allMaterials.includes(o.material)) allMaterials.push(o.material);
      if (o.geometry && !allGeometries.includes(o.geometry)) allGeometries.push(o.geometry);
    });
  });

  root.userData.cleanup = () => {
    timelines.forEach(t => t.kill());
    gsap.killTweensOf(dom.scale);
    gsap.killTweensOf(tr.scale);
    gsap.killTweensOf(br.scale);
    allMaterials.forEach(m => { try { m.dispose(); } catch (e) {} });
    allGeometries.forEach(g => { try { g.dispose(); } catch (e) {} });
    allText.forEach(t => {
      t.traverse(o => {
        if (o.geometry) { try { o.geometry.dispose(); } catch (e) {} }
        if (o.material) { try { o.material.dispose(); } catch (e) {} }
      });
    });
  };

  return root;
}
